struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn heatmap(t: f32) -> vec3f {
  let x = clamp(t, 0.0, 1.0);
  let c0 = vec3f(0.02, 0.05, 0.16);
  let c1 = vec3f(0.04, 0.32, 0.82);
  let c2 = vec3f(0.28, 0.82, 1.0);
  let c3 = vec3f(0.95, 0.98, 1.0);
  if (x < 0.35) { return mix(c0, c1, x / 0.35); }
  if (x < 0.72) { return mix(c1, c2, (x - 0.35) / 0.37); }
  return mix(c2, c3, (x - 0.72) / 0.28);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let grid = uv * vec2f(32.0, 28.0);
  let cell = fract(grid);
  let id = floor(grid);
  let street = 1.0 - smoothstep(0.05, 0.11, min(cell.x, cell.y));

  let downtown = exp(-length((uv - vec2f(0.70, 0.42)) * vec2f(1.9, 2.5)) * 3.1);
  let lakefront = exp(-abs(uv.x - 0.84) * 16.0) * smoothstep(0.12, 0.88, 1.0 - uv.y);
  let noise = hash(id) * 0.5 + hash(id + vec2f(19.0, 7.0)) * 0.22;
  let pulse = 0.88 + 0.12 * sin(params.time * 1.3 + uv.x * 7.0);

  var activity = street * (0.22 + downtown * 1.05 + lakefront * 1.15);
  activity += downtown * 0.32;
  activity *= (0.5 + noise) * pulse;

  let water = smoothstep(0.86, 0.91, uv.x);
  let col = mix(heatmap(activity), vec3f(0.03, 0.10, 0.20), water);
  return vec4f(col, 1.0);
}
